'use strict';

/* eslint-disable max-lines */

// MODULES //

var logger = require( 'debug' );
var lowercase = require( '@stdlib/string/lowercase' );
var trim = require( '@stdlib/string/trim' );
var replace = require( '@stdlib/string/replace' );
var format = require( '@stdlib/string/format' );
var project = require( './project.js' );
var plainText = require( './plain_text.js' );
var account = require( './account.js' );
var hash = require( './hash.js' );


// VARIABLES //

var debug = logger( 'markdown-to-semantic-document:nodes' );


// FUNCTIONS //

/**
* Allocates a document-local semantic node ID.
*
* @private
* @param {Object} parent - parent semantic node
* @param {string} type - node type
* @returns {string} node ID
*/
function allocate( parent, type ) {
	var ordinal;
	var id;

	// Counters are local to a semantic parent and node type. Prefixing the parent ID produces deterministic hierarchical IDs without relying on source offsets...
	ordinal = parent.internal.counters[ type ] || 0;
	id = format( '%s[%s]', type, ordinal );
	parent.internal.counters[ type ] = ordinal + 1;
	if ( parent.id ) {
		id = format( '%s/%s', parent.id, id );
	}
	return id;
}

/**
* Returns a payload and semantic hash pair.
*
* @private
* @param {Object} payload - payload
* @param {Object} semantics - semantic annotations
* @returns {Object} hash pair
*/
function hashes( payload, semantics ) {
	var payloadHash = hash( payload );

	// Payload identity captures renderable content. Semantic identity additionally commits to classification, execution, or other meaning assigned by conversion:
	return {
		'payloadHash': payloadHash,
		'semanticHash': hash({
			'payloadHash': payloadHash,
			'semantics': semantics
		})
	};
}

/**
* Returns a normalized code language.
*
* @private
* @param {(string|null)} lang - authored code language
* @returns {(string|null)} normalized language
*/
function language( lang ) {
	var value;

	if ( !lang ) {
		return null;
	}
	value = lowercase( lang );

	// Normalize common fence aliases while retaining unknown language names. The authored spelling remains available separately on semantic code nodes...
	if ( value === 'js' || value === 'node' ) {
		return 'javascript';
	}
	if ( value === 'sh' || value === 'shell' || value === 'console' ) {
		return 'bash';
	}
	if ( value === 'c++' ) {
		return 'cpp';
	}
	return value;
}

/**
* Returns code role and execution intent.
*
* @private
* @param {Object} parent - parent semantic node
* @param {(string|null)} lang - normalized language
* @param {Array} directives - effective directives
* @param {Object} state - conversion state
* @returns {Object} classification
*/
function classifyCode( parent, lang, directives, state ) {
	var explicitRun = false;
	var intent = 'unknown';
	var roles = parent.internal.roles;
	var role = 'unknown';
	var i;

	// An explicit run directive can opt JavaScript into execution even when its document location alone is not a recognized setup/example context...
	for ( i = 0; i < directives.length; i++ ) {
		if ( directives[ i ].family === 'run' || directives[ i ].family === 'run-disable' ) {
			explicitRun = true;
		}
	}
	if ( lang === 'javascript' ) {
		// Tutorial JavaScript is sequential executable material regardless of the topic heading under which it appears...
		if ( state.options.profile === 'tutorial' ) {
			role = 'example';
			intent = 'candidate';
		} else if ( roles[ 0 ] === 'usage' && roles.indexOf( 'c' ) === -1 && roles.indexOf( 'cli' ) === -1 ) {
			// Top-level JavaScript in a JS usage section is either initial setup or an API-specific usage example. Nested C/CLI sections explicitly opt out...
			if ( parent.type === 'topic' ) {
				role = 'usage-example';
			} else if ( parent.internal.javascriptCodes === 0 ) {
				role = 'setup';
			}
			intent = ( role === 'unknown' ) ? 'unknown' : 'candidate';
		} else if ( roles[ 0 ] === 'examples' && roles.indexOf( 'c' ) === -1 && roles.indexOf( 'cli' ) === -1 ) {
			// JavaScript in the main examples section is independently executable...
			role = 'example';
			intent = 'candidate';
		} else if ( explicitRun ) {
			role = 'example';
			intent = 'candidate';
		}
	} else if ( lang === 'bash' ) {
		// Non-JavaScript blocks retain useful display roles but are not execution candidates for, e.g., an intended JavaScript notebook consumer...
		role = 'shell-session';
		intent = 'not-requested';
	} else if ( lang === 'text' && roles.indexOf( 'usage' ) >= 0 && parent.type === 'topic' ) {
		role = 'signature';
		intent = 'not-requested';
	} else if ( lang ) {
		role = 'snippet';
		intent = 'not-requested';
	}
	debug( 'Classified code: parent=%s language=%s role=%s intent=%s directives=%d', parent.id || 'document', lang || 'none', role, intent, directives.length );
	return {
		'role': role,
		'intent': intent
	};
}

/**
* Returns an embedded code role and execution intent.
*
* @private
* @param {(string|null)} lang - normalized language
* @param {string} profile - semantic profile
* @returns {Object} classification
*/
function classifyEmbeddedCode( lang, profile ) {
	// Nested tutorial JavaScript remains embedded in authored Markdown structure but is still meaningful executable material...
	if ( profile === 'tutorial' && lang === 'javascript' ) {
		return {
			'role': 'example',
			'intent': 'candidate',
			'reason': 'Nested tutorial JavaScript is an execution candidate.'
		};
	}
	return {
		'role': 'unknown',
		'intent': 'unknown',
		'reason': 'Nested code is not a standalone execution candidate.'
	};
}

/**
* Returns a normalized reference identifier.
*
* @private
* @param {string} value - reference identifier
* @returns {string} normalized identifier
*/
function normalizeIdentifier( value ) {
	return lowercase( trim( replace( value, /[\t\n\r ]+/g, ' ' ) ) );
}

/**
* Accounts for nested transformations and records embedded code.
*
* @private
* @param {Object} state - conversion state
* @param {Object} node - source MDAST node
* @param {string} target - target semantic ID
* @param {boolean} normalizeSpans - boolean indicating whether related spans are normalized
* @returns {void}
*/
function inspectNested( state, node, target, normalizeSpans ) {
	var classification;
	var identifier;
	var children;
	var resource;
	var reason;
	var spans;
	var lang;
	var i;

	if ( node.type === 'linkReference' || node.type === 'imageReference' ) {
		// Projected references resolve inline, so account for that nested source transformation against the enclosing semantic flow node...
		identifier = normalizeIdentifier( node.identifier );
		if ( state.definitions[ identifier ] ) {
			account( state, node, 'transformed', 'reference', 'Resolved reference against an ordered definition resource.', [ target ] );
		}
	}
	if ( node.type === 'code' ) {
		lang = language( node.lang || null );
		classification = classifyEmbeddedCode( lang, state.options.profile );

		// Code nested inside lists or block quotes cannot become a top-level semantic cell without changing structure. Index it as an embedded-code resource...
		resource = {
			'id': format( 'embedded-code[%s]', state.document.resources.embeddedCode.length ),
			'language': lang,
			'lang': node.lang || null,
			'meta': node.meta || null,
			'value': node.value,
			'role': classification.role,
			'execution': {
				'intent': classification.intent,
				'disabled': false,
				'expected': 'success',
				'reason': classification.reason
			},
			'directiveRefs': [],
			'source': state.provenance.source( [ node ] ),
			'sourceHash': state.provenance.sourceHash( [ node ] ),
			'payloadHash': hash( node.value )
		};
		state.document.resources.embeddedCode.push( resource );
		debug( 'Indexed embedded code resource: id=%s language=%s target=%s', resource.id, resource.language || 'none', target );
	}
	if ( node.children ) {
		// Recurse through the original MDAST to find transformations hidden beneath containers represented by a single Markdown/heading/summary node...
		children = node.children;
		spans = ( normalizeSpans ) ? (
			project.relatedSpanIndexes( children )
		) : null;
		reason = 'Removed balanced generated styling wrapper.';
		for ( i = 0; i < children.length; i++ ) {
			if ( spans && spans[ i ] ) {
				account( state, children[ i ], 'transformed', 'related-span', reason, [ target ] );
			}
			inspectNested( state, children[ i ], target, normalizeSpans );
		}
	}
}

/**
* Appends accounting records for represented nodes.
*
* @private
* @param {Object} state - conversion state
* @param {Array} mdast - source MDAST nodes
* @param {string} target - semantic target ID
* @param {string} classification - source classification
* @returns {void}
*/
function represented( state, mdast, target, classification ) {
	var i;

	// A semantic node may combine multiple adjacent source blocks. Give each root block the same target while preserving one accounting record per source node...
	for ( i = 0; i < mdast.length; i++ ) {
		account( state, mdast[ i ], 'represented-in-flow', classification, 'Represented in canonical document flow.', [ target ] );
	}
}

/**
* Returns execution metadata and updates directive resources.
*
* @private
* @param {Array} directives - effective directives
* @param {string} id - target code ID
* @param {string} intent - execution intent
* @param {Object} state - conversion state
* @returns {Object} execution metadata
*/
function execution( directives, id, intent, state ) {
	var expected = 'success';
	var disabled = false;
	var reason = null;
	var parsed;
	var i;

	for ( i = 0; i < directives.length; i++ ) {
		// Record the relationship in both the directive resource and the source accounting entry so either view can identify the affected code node...
		directives[ i ].targetRefs.push( id );
		state.directiveAccounting[ directives[ i ].id ].targetRefs.push( id );
		if ( directives[ i ].family === 'run-disable' ) {
			disabled = true;
			reason = 'Disabled by an explicit run-disable directive.';
		}
		parsed = directives[ i ].parsed;

		// Expected failure is semantic execution metadata; it does not mean that conversion itself encountered an error...
		if ( directives[ i ].family === 'run' && parsed && parsed.throws ) {
			expected = 'throws';
		}
	}
	debug( 'Created code execution metadata: id=%s intent=%s disabled=%s expected=%s directives=%d', id, intent, disabled, expected, directives.length );
	return {
		'intent': intent,
		'disabled': disabled,
		'expected': expected,
		'reason': reason
	};
}

/**
* Returns the semantic content of a directive.
*
* @private
* @param {Object} directive - directive resource
* @returns {Object} semantic directive content
*/
function directiveSemantics( directive ) {
	// Directive IDs are location-dependent and should not define code semantics, so hash the normalized family/payload such that equivalent directives remain equivalent:
	return {
		'family': directive.family,
		'parsed': directive.parsed
	};
}

/**
* Logs and returns a semantic node.
*
* @private
* @param {Object} node - semantic node
* @returns {Object} semantic node
*/
function created( node ) {
	debug( 'Created semantic node: id=%s type=%s role=%s', node.id, node.type, node.role || 'none' );
	return node;
}


// MAIN //

/**
* Creates a heading semantic node.
*
* @private
* @param {Object} parent - parent semantic node
* @param {Object} mdast - source heading node
* @param {Object} state - conversion state
* @returns {Object} semantic heading
*/
function heading( parent, mdast, state ) {
	var pair;
	var ast;
	var out;
	var i;

	ast = {
		'type': 'root',
		'children': []
	};

	// Project inline heading children into a portable root rather than preserving a redundant MDAST heading wrapper alongside the semantic depth/text fields...
	for ( i = 0; i < mdast.children.length; i++ ) {
		ast.children.push( project( mdast.children[ i ], state, false ) );
	}
	out = {
		'type': 'heading',
		'id': allocate( parent, 'heading' ),
		'depth': mdast.depth,
		'text': plainText( mdast ),
		'ast': ast,
		'source': state.provenance.source( [ mdast ] )
	};
	pair = hashes( ast, {
		'type': out.type,
		'depth': out.depth
	});
	out.payloadHash = pair.payloadHash;
	out.semanticHash = pair.semanticHash;

	// Account for both the root heading and any nested reference transformations...
	represented( state, [ mdast ], out.id, 'heading' );
	inspectNested( state, mdast, out.id, false );
	return created( out );
}

/**
* Creates a summary semantic node.
*
* @private
* @param {Object} parent - parent semantic node
* @param {Object} mdast - source blockquote node
* @param {Object} state - conversion state
* @returns {Object} semantic summary
*/
function summary( parent, mdast, state ) {
	var pair;
	var out;
	var ast;

	// The block quote wrapper signals summary semantics but is not needed in the projected content, so retain only its projected children under a root node...
	ast = project( mdast, state, false );
	out = {
		'type': 'summary',
		'id': allocate( parent, 'summary' ),
		'text': plainText( mdast ),
		'ast': {
			'type': 'root',
			'children': ast.children
		},
		'source': state.provenance.source( [ mdast ] )
	};

	pair = hashes( out.ast, {
		'type': out.type
	});
	out.payloadHash = pair.payloadHash;
	out.semanticHash = pair.semanticHash;

	represented( state, [ mdast ], out.id, 'summary' );
	inspectNested( state, mdast, out.id, false );
	return created( out );
}

/**
* Creates a Markdown semantic node.
*
* @private
* @param {Object} parent - parent semantic node
* @param {Array} mdast - source MDAST nodes
* @param {Object} state - conversion state
* @returns {Object} semantic Markdown
*/
function markdown( parent, mdast, state ) {
	var normalizeSpans;
	var pair;
	var ast;
	var out;
	var i;

	// Generated related-package spans are styling artifacts. Normalize them only in characterized stdlib-aware sections, leaving generic/authored HTML untouched:
	normalizeSpans = (
		state.options.profile !== 'generic' &&
		parent.internal.roles.indexOf( 'related' ) >= 0
	);
	ast = {
		'type': 'root',
		'children': []
	};

	// Preserve each contiguous MDAST block as a child of one portable root. This keeps internal Markdown structure without fragmenting semantic document flow...
	for ( i = 0; i < mdast.length; i++ ) {
		ast.children.push( project( mdast[ i ], state, normalizeSpans ) );
	}
	out = {
		'type': 'markdown',
		'id': allocate( parent, 'markdown' ),
		'role': 'prose',
		'ast': ast,
		'plainText': plainText({
			'type': 'root',
			'children': mdast
		}),
		'source': state.provenance.source( mdast )
	};
	pair = hashes( ast, {
		'type': out.type,
		'role': out.role
	});
	out.payloadHash = pair.payloadHash;
	out.semanticHash = pair.semanticHash;
	represented( state, mdast, out.id, 'markdown' );

	// Nested nodes need separate accounting only when projection transforms or indexes them; ordinary descendants remain represented by their root block...
	for ( i = 0; i < mdast.length; i++ ) {
		inspectNested( state, mdast[ i ], out.id, normalizeSpans );
	}
	return created( out );
}

/**
* Creates a code semantic node.
*
* @private
* @param {Object} parent - parent semantic node
* @param {Object} mdast - source code node
* @param {Array} directives - effective directive resources
* @param {Object} state - conversion state
* @returns {Object} semantic code
*/
function code( parent, mdast, directives, state ) {
	var classification;
	var sourceValue;
	var normalized;
	var out;
	var id;

	// Classification depends on normalized language, structural context, and all effective directives. Source style is detected from the exact authored slice...
	normalized = language( mdast.lang || null );
	classification = classifyCode( parent, normalized, directives, state );
	sourceValue = replace( state.provenance.slice( mdast ), /^\s+/, '' );
	id = allocate( parent, 'code' );
	out = {
		'type': 'code',
		'id': id,
		'semanticKey': format( '%s/%s-%s', parent.internal.semanticKey, classification.role, parent.internal.counters.code-1 ),
		'language': normalized,
		'lang': mdast.lang || null,
		'meta': mdast.meta || null,
		'sourceStyle': ( /^(?:`{3,}|~{3,})/.test( sourceValue ) ) ? 'fenced' : 'indented',
		'value': mdast.value,
		'role': classification.role,
		'execution': execution( directives, id, classification.intent, state ),
		'directiveRefs': directives.map( directiveID ),
		'source': state.provenance.source( [ mdast ] ),
		'sourceHash': state.provenance.sourceHash( [ mdast ] ),
		'payloadHash': hash( replace( mdast.value, /\r\n?/g, '\n' ) )
	};

	// Payload hashes normalize line endings inside code. Semantic hashes additionally include role, execution policy, and directive meaning:
	out.semanticHash = hash({
		'payloadHash': out.payloadHash,
		'role': out.role,
		'execution': out.execution,
		'directives': directives.map( directiveSemantics )
	});

	// This counter distinguishes the first usage-level JavaScript block (setup) from later ungrouped JavaScript blocks in the same semantic parent:
	parent.internal.javascriptCodes += ( normalized === 'javascript' ) ? 1 : 0;
	represented( state, [ mdast ], out.id, 'code' );
	return created( out );
}

/**
* Returns a directive ID.
*
* @private
* @param {Object} directive - directive resource
* @returns {string} directive ID
*/
function directiveID( directive ) {
	return directive.id;
}

/**
* Creates a math semantic node.
*
* @private
* @param {Object} parent - parent semantic node
* @param {Object} mdast - source code node
* @param {(Object|null)} metadata - equation metadata
* @param {Object} state - conversion state
* @returns {Object} semantic math
*/
function math( parent, mdast, metadata, state ) {
	// A `math` fence is transformed from code syntax into display-TeX semantics; optional metadata originates from the immediately preceding equation wrapper:
	var out = {
		'type': 'math',
		'id': allocate( parent, 'math' ),
		'format': 'tex',
		'display': true,
		'value': mdast.value,
		'label': ( metadata ) ? metadata.label : null,
		'alt': ( metadata ) ? metadata.alt : null,
		'source': state.provenance.source( [ mdast ], 'math-fence' ),
		'sourceHash': state.provenance.sourceHash( [ mdast ] ),
		'payloadHash': hash( replace( mdast.value, /\r\n?/g, '\n' ) )
	};
	out.semanticHash = hash({
		'payloadHash': out.payloadHash,
		'format': out.format,
		'display': out.display,
		'label': out.label,
		'alt': out.alt
	});

	// Use a transformed disposition because downstream renderers no longer receive this source node as a code fence...
	account( state, mdast, 'transformed', 'math-fence', 'Represented as a semantic math node.', [ out.id ] );
	return created( out );
}

/**
* Creates a raw semantic node.
*
* @private
* @param {Object} parent - parent semantic node
* @param {Object} mdast - source raw node
* @param {string} classification - raw classification
* @param {Object} state - conversion state
* @returns {Object} semantic raw node
*/
function raw( parent, mdast, classification, state ) {
	var pair;
	var out;

	// Raw nodes are the lossless escape hatch for unknown or malformed constructs. Their classification explains why conversion did not normalize the payload:
	out = {
		'type': 'raw',
		'id': allocate( parent, 'raw' ),
		'format': ( mdast.type === 'html' ) ? 'html' : mdast.type,
		'value': mdast.value || state.provenance.slice( mdast ),
		'classification': classification,
		'source': state.provenance.source( [ mdast ] ),
		'sourceHash': state.provenance.sourceHash( [ mdast ] )
	};
	pair = hashes( out.value, {
		'type': out.type,
		'format': out.format,
		'classification': out.classification
	});
	out.payloadHash = pair.payloadHash;
	out.semanticHash = pair.semanticHash;
	represented( state, [ mdast ], out.id, 'raw' );
	return created( out );
}

/**
* Creates a frontmatter semantic node.
*
* @private
* @param {Object} parent - parent semantic node
* @param {Object} mdast - source frontmatter node
* @param {Object} state - conversion state
* @returns {Object} semantic frontmatter node
*/
function frontmatter( parent, mdast, state ) {
	// Frontmatter remains opaque. Parsing YAML here would introduce schema and coercion behavior unrelated to Markdown-to-semantic conversion:
	var out = {
		'type': 'frontmatter',
		'id': allocate( parent, 'frontmatter' ),
		'format': mdast.type,
		'value': mdast.value,
		'source': state.provenance.source( [ mdast ] ),
		'sourceHash': state.provenance.sourceHash( [ mdast ] ),
		'payloadHash': hash( mdast.value )
	};
	out.semanticHash = hash({
		'payloadHash': out.payloadHash,
		'format': out.format
	});
	represented( state, [ mdast ], out.id, 'frontmatter' );
	return created( out );
}

/**
* Creates a thematic-break semantic node.
*
* @private
* @param {Object} parent - parent semantic node
* @param {Object} mdast - source thematic-break node
* @param {Object} state - conversion state
* @returns {Object} semantic thematic break
*/
function thematicBreak( parent, mdast, state ) {
	// A thematic break has no textual payload, so hash its semantic marker to give it stable identity independent of the authored Markdown delimiter style:
	var out = {
		'type': 'thematicBreak',
		'id': allocate( parent, 'thematicBreak' ),
		'source': state.provenance.source( [ mdast ] ),
		'payloadHash': hash({
			'type': 'thematicBreak'
		})
	};
	out.semanticHash = hash({
		'payloadHash': out.payloadHash,
		'type': out.type
	});
	represented( state, [ mdast ], out.id, 'thematic-break' );
	return created( out );
}

/**
* Creates an image media semantic node.
*
* @private
* @param {Object} parent - parent semantic node
* @param {Object} mdast - source paragraph node
* @param {Object} state - conversion state
* @returns {Object} semantic media node
*/
function media( parent, mdast, state ) {
	var image;
	var out;

	// Projection resolves image references while preserving the authored URL and definition relationship needed by downstream resource-rewriting wrappers...
	image = project( mdast.children[ 0 ], state, false );
	out = {
		'type': 'media',
		'id': allocate( parent, 'media' ),
		'mediaType': 'image',
		'authoredUrl': image.url || null,
		'renderedUrl': null,
		'alt': image.alt || '',
		'alignment': null,
		'label': null,
		'definitionRef': image.definitionRef || null,
		'source': state.provenance.source( [ mdast ] ),
		'sourceHash': state.provenance.sourceHash( [ mdast ] ),
		'payloadHash': hash( image )
	};
	out.semanticHash = hash({
		'payloadHash': out.payloadHash,
		'mediaType': out.mediaType,
		'alignment': out.alignment,
		'label': out.label
	});
	represented( state, [ mdast ], out.id, 'media' );
	inspectNested( state, mdast, out.id, false );
	return created( out );
}


// EXPORTS //

module.exports = {
	'allocate': allocate,
	'heading': heading,
	'summary': summary,
	'markdown': markdown,
	'code': code,
	'math': math,
	'raw': raw,
	'frontmatter': frontmatter,
	'thematicBreak': thematicBreak,
	'media': media
};
